parameters.jsCode:
const action = $fromAI('action', 'Action Premiere: import_sequence, create_timeline, color_grade, add_titles, export_sequence, sync_audio, create_multicam');
const detail = $fromAI('detail', 'Détails spécifiques pour le script Premiere Pro');

const templates = {
  import_sequence: `// naset_premiere_import.jsx — Import Séquences N'Aset OFM
// Négus Dja / OFM Studio — Premiere Pro ExtendScript

#include "json2.js"

var PROJECT_NAME = "NasetOFM_CourtMetrage_v1";
var SEQUENCE_SETTINGS = {
  width:     3840,
  height:    2160,
  frameRate: 24,
  name:      "Naset_Sequence_4K_24fps"
};

function importRenderSequences(folderPath) {
  var project = app.project;

  // Créer bin Renders
  var rendersBin = project.rootItem.createBin("Naset_Renders");

  // Importer les renders Blender
  var importFiles = new Array();
  var folder = new Folder(folderPath);

  if (!folder.exists) {
    alert("[OFM] Dossier introuvable : " + folderPath);
    return;
  }

  var files = folder.getFiles("Naset_S*.png");
  for (var i = 0; i < files.length; i++) {
    importFiles.push(files[i].fsName);
  }

  if (importFiles.length === 0) {
    alert("[OFM] Aucun render trouvé dans " + folderPath);
    return;
  }

  // Import en tant que séquence image
  project.importFiles(importFiles, true, rendersBin, true);
  $.writeln("[OFM] ✓ " + importFiles.length + " frames importées");
  return rendersBin;
}

function createMainSequence() {
  var project = app.project;

  // Créer séquence principale
  project.createNewSequence(SEQUENCE_SETTINGS.name, "desktop-4K");

  var seq = project.activeSequence;
  if (!seq) {
    alert("[OFM] Impossible de créer la séquence");
    return;
  }

  $.writeln("[OFM] ✓ Séquence " + SEQUENCE_SETTINGS.name + " créée");
  return seq;
}

// Exécution
var seq = createMainSequence();
if (seq) {
  // Importer depuis le dossier renders Blender
  // MODIFIE CE CHEMIN selon ton système
  importRenderSequences("/chemin/vers/renders/Naset/");
  alert("[OFM] ✓ Import terminé !");
}`,

  color_grade: `// naset_premiere_colorgrade.jsx — Color Grade N'Aset OFM
// Palette : Or Sacré + Peau Chaude + Ombres Profondes
// Négus Dja / OFM Studio

function applyNasetLookLUT(clipItem) {
  // Applique le Lumetri Color avec les valeurs OFM
  var effect = clipItem.components.addComponent("Lumetri Color");
  if (!effect) return;

  var p = effect.properties;

  // Correction de base
  p["Exposure"].setValue(0.1);
  p["Contrast"].setValue(15);
  p["Highlights"].setValue(-20);
  p["Shadows"].setValue(10);
  p["Whites"].setValue(5);
  p["Blacks"].setValue(-10);

  // Couleurs créatives (teinte Or Sacré)
  p["Color Temperature"].setValue(200);  // plus chaud
  p["Tint"].setValue(-5);
  p["Saturation"].setValue(110);
  p["Vibrance"].setValue(15);

  $.writeln("[OFM] ✓ Lumetri appliqué sur " + clipItem.name);
}

function applyToAllClips() {
  var seq = app.project.activeSequence;
  if (!seq) { alert("Ouvre une séquence d'abord."); return; }

  var track = seq.videoTracks[0];
  for (var i = 0; i < track.clips.numItems; i++) {
    applyNasetLookLUT(track.clips[i]);
  }

  alert("[OFM] ✓ Color grade N'Aset appliqué sur " + track.clips.numItems + " clips !");
}

applyToAllClips();`,

  export_sequence: `// naset_premiere_export.jsx — Export Court Métrage N'Aset OFM
// Format : ProRes 4444 · 4K · 24fps
// Négus Dja / OFM Studio

function exportNasetSequence() {
  var project   = app.project;
  var sequence  = project.activeSequence;

  if (!sequence) {
    alert("[OFM] Aucune séquence active.");
    return;
  }

  var exporter = app.encoder;

  // Chemin export — MODIFIE SELON TON SYSTÈME
  var outputPath = "/chemin/vers/export/NasetOFM_CourtMetrage_v1.mov";

  // Préset ProRes 4444 (GUID Premiere Pro)
  var presetPath = "/Applications/Adobe Premiere Pro/presets/NasetOFM_ProRes4444.epr";

  // Ajouter à la file d'encodage
  exporter.encodeSequence(
    sequence,
    outputPath,
    presetPath,
    app.encoder.ENCODE_WORKAREA,  // ou ENCODE_ENTIRE
    true  // removeOnCompletion
  );

  exporter.startBatch();
  $.writeln("[OFM] ✓ Export lancé vers " + outputPath);
  alert("[OFM] Export NasetOFM en cours...\nVérifie Adobe Media Encoder.");
}

exportNasetSequence();`
};

const script = templates[action] || templates.import_sequence;

return {
  action,
  detail,
  script,
  filename: `naset_premiere_${action}.jsx`,
  instructions: `Dans Premiere Pro : File > Scripts > Run Script → sélectionne ce fichier .jsx`
};

